@charset "UTF-8";

/* ==========  variable  ========== */

:root {
    --font-family: "Montserrat", sans-serif;
    --background-body: #f3f3f3;
    --main-color-black: #000;
    --main-color-white: #fff;
    --main-color-primary: #373737;
