        from 0deg at 50.18% 132.29%,
        #1374cb 21.53613343834877deg,
        #d34ecd 76.87500178813934deg,
        #31bea9 151.875deg,
        #3559de 247.5deg,
        #17739e 316.75004482269287deg
    );
    --main-hover-bg-black: #373737;
    --font-size-default: 18px;
    --line-height-default: normal;
    --font-weight-default: 400;
    --container-width: 1856px;
