/*===== animation-first-block  =====*/

@keyframes bronza {
    0% {
        transform: rotate(0deg) scale(1);
        filter: none;
    }

    45% {
        transform: rotate(-90deg) scale(0.8);
        filter: blur(2px);
    }

    90% {
        transform: rotate(0deg) scale(1);
        filter: none;
    }

    100% {
        transform: rotate(0deg) scale(1);
        filter: none;
    }
}

@keyframes serebro {
    0% {
        transform: rotate(0deg) scale(1) translate(0px);
        filter: none;
    }

    45% {
        transform: scale(0.8) translate(66px, 53px) rotate(-90deg);
        filter: blur(2px);
    }

    90% {
        transform: rotate(0deg) scale(1);
        filter: none;
    }

    100% {
        transform: rotate(0deg) scale(1);
        filter: none;
    }
}

@keyframes gold {
    0% {
        transform: rotate(0deg) scale(1) translate(0px);
        filter: none;
    }

    45% {
        transform: scale(0.8) translate(75px, 40px) rotate(-90deg);
        filter: blur(2px);
    }

    90% {
        transform: rotate(0deg) scale(1) translate(0px);
        filter: none;
    }

    100% {
        transform: rotate(0deg) scale(1) translate(0px);
        filter: none;
    }
}

@keyframes platinum {
    0% {
        transform: rotate(0deg) scale(1) translate(0px);
        filter: none;
    }

    45% {
        transform: scale(0.8) translate(-51px, -50px) rotate(-90deg);
        filter: blur(2px);
    }

    90% {
        transform: rotate(0deg) scale(1) translate(0px);
        filter: none;
    }

    100% {
        transform: rotate(0deg) scale(1) translate(0px);
        filter: none;
    }
}

@keyframes small-1 {
    0% {
        transform: translate(0px, 0px);
