    animation: 11s ease-in-out infinite diet-name-animated;
    position: relative;
    z-index: 1;
}

.prod-diet-animated__watch {
    position: absolute;
    top: 52%;
    left: 51%;
    transform: translate(-50%, -50%);
    width: 702px;
    height: 702px;
}

.prod-diet-animated__watch img {
    width: 100%;
    height: 100%;
    -o-object-fit: contain;
    object-fit: contain;
}

.prod-diet-animated__watch::before {
    content: "";
    position: absolute;
    top: 55%;
    left: 57%;
    transform-origin: 15% 21%;
    width: 157px;
    height: 109px;
    background: url("https://moscow.krugozor-clinic.ru/bitrix/templates/krugozor/assets/img/other-page/products/diet-block/small.svg") no-repeat;
    animation: 11s ease-in-out infinite watch-decor-one;
    z-index: 1;
    background-size: contain;
}

.prod-diet-animated__watch::after {
    content: "";
    position: absolute;
    top: 35%;
    left: 50%;
    transform-origin: 30% 102%;
    width: 27px;
    height: 187px;
    background: url("https://moscow.krugozor-clinic.ru/bitrix/templates/krugozor/assets/img/other-page/products/diet-block/big.svg") no-repeat;
    animation: 11s ease-in-out infinite watch-decor-two;
    background-size: contain;
}

@keyframes watch-decor-one {
    0% {
        transform: translate(-50%, -50%) rotate(-34deg);
    }

    10% {
        transform: translate(-50%, -50%) rotate(-30deg);
    }

    20% {
        transform: translate(-50%, -50%) rotate(-34deg);
    }

    50% {
        transform: translate(-50%, -50%) rotate(4deg);
    }

    60% {
        transform: translate(-50%, -50%) rotate(0deg);
    }

    70% {
        transform: translate(-50%, -50%) rotate(4deg);
    }

    100% {
        transform: translate(-50%, -50%) rotate(-34deg);
    }
}

@keyframes watch-decor-two {
    0% {
        transform: translate(-50%, -50%);
    }

    10% {
        transform: translate(-50%, -50%) rotate(8deg);
    }

    20% {
        transform: translate(-50%, -50%);
    }

    50% {
        transform: translate(-50%, -50%) rotate(156deg);
    }

    60% {
        transform: translate(-50%, -50%) rotate(148deg);
    }

    70% {
        transform: translate(-50%, -50%) rotate(156deg);
    }

    100% {
        transform: translate(-50%, -50%);
    }
}

@keyframes diet-animated {
    0% {
        transform: scale(1);
    }

    10% {
        transform: scale(1.02);
    }

    20% {
        transform: scale(1);
    }

    50% {
        transform: scale(1.1) translateY(-6px);
    }

    60% {
        transform: scale(1.08) translateY(-6px);
    }

    70% {
        transform: scale(1.1) translateY(-6px);
    }

    100% {
        transform: scale(1);
    }
}

@keyframes diet-name-animated {
    0% {
        transform: translateY(0);
    }

    10% {
        transform: translateY(-3px);
    }

    20% {
        transform: translateY(0);
    }

    50% {
        transform: translateY(-8px);
    }

    60% {
        transform: translateY(-5px);
    }

    70% {
        transform: translateY(-8px);
    }

    100% {
        transform: translateY(0);
    }
}

