    background: url("https://moscow.krugozor-clinic.ru/bitrix/templates/krugozor/assets/img/rec/bg.png") no-repeat center / contain;
    pointer-events: none;
}

.rec-step {
    padding: 46px 70px 0px 70px;
    border-bottom: 1px dashed #c6c6c6;
    margin-bottom: 34px;
}

.rec-step__list {
    max-width: 1090px;
    width: 100%;
    display: flex;
}

.rec-step__item {
    width: 16.666%;
    position: relative;
    display: flex;
}

.rec-step__item:not(:last-child):after {
    content: "";
    position: absolute;
    bottom: -1px;
    left: 21px;
    width: 0;
    height: 2px;
    background: #73bafa;
    transition: all 0.3s ease 0s;
    z-index: 1;
}

.rec-step__item._selected::after {
    width: 100%;
}

.rec-step__num {
    display: flex;
    justify-content: center;
    color: #d7d7d7;
    font-size: 24px;
    font-weight: 600;
    line-height: 58px;
    position: relative;
    width: 49px;
    transition: all 0.3s ease 0s;
}

.rec-step__num::before {
    content: "";
    position: absolute;
    bottom: -6px;
    left: 50%;
    transform: translateX(-50%);
    width: 12px;
    height: 12px;
    background: #e9e9e9;
    border-radius: 50%;
    transition: all 0.3s ease 0s;
}

.rec-step__item._selected .rec-step__num._active {
    color: #73bafa;
    font-size: 36px;
    line-height: 58px;
}

.rec-step__item._selected .rec-step__num::before {
    background: #73bafa;
}

.rec-step__item._selected + .rec-step__item .rec-step__num::before {
    background: #73bafa;
}

.rec-content {
    padding: 0px 37px 78px 70px;
    z-index: 1;
    position: relative;
}

.rec-content::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: 3;
    background: #fff;
    opacity: 0;
    transition: all 0.3s ease 0s;
    pointer-events: none;
}

.rec-content._loaded::before {
    opacity: 1;
}

.rec-content::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 50px;
    height: 50px;
    background: url("https://moscow.krugozor-clinic.ru/bitrix/templates/krugozor/assets/img/rec/load.svg") no-repeat center / contain;
    z-index: 3;
    opacity: 0;
    transition: all 0.3s ease 0s;
    pointer-events: none;
}

.rec-content._loaded::after {
    opacity: 1;
}

.rec-content._loaded .r-step-content {
    min-height: 399px;
}

.rec-top__title {
    color: #373737;
    font-size: 48px;
    font-weight: 500;
    line-height: 78px;
}

.r-step-content {
    display: none;
    flex-direction: column;
}

.r-step-content._show {
    display: flex;
}

.rec-clinic__list {
    display: flex;
    flex-direction: column;
    gap: 16px;
    padding-right: 33px;
}

._overflow {
    overflow: auto;
}

._overflow::-webkit-scrollbar {
    width: 3px;
}

._overflow::-webkit-scrollbar-track {
    background: #e9e9e9;
}

._overflow::-webkit-scrollbar-thumb {
    background-color: #73f3e0;
    border-radius: 20px;
}

