/* Стили для панели выбора */
.eye-panel {
	position: absolute;
	top: 0;
	left: 50%;
	transform: translate(-50%, -150%);
	background: #3fa6d7;
	border-radius: 0 0 22px 22px;
	color: var(--main-color-white);
	z-index: 9;
	padding: 20px 30px;
	opacity: 0;
	pointer-events: none;
	transition: all 0.3s ease 0s;
	max-width: 410px;
	width: 100%;
}
.eye-panel._show {
	transform: translate(-50%, 0);
	opacity: 1;
	pointer-events: auto;
}
.eye-panel._roll {
	transform: translate(-50%, -100%);
}
.eye-panel__select {
	display: flex;
	align-items: center;
	gap: 10px;
}
.eye-panel__nobg,
.eye-panel__bg {
	padding: 10px 15px;
	display: flex;
	justify-content: center;
	align-items: center;
	outline: 1px solid #fff;
	font-size: 16px;
	font-weight: 700;
	cursor: pointer;
}
.eye-panel__nobg._selected {
	outline-width: 2px;
}
.eye-panel__bg._selected {
	outline-width: 2px;
}
.eye-panel__bg {
	background: #000;
}
.eye-panel__small {
	font-size: 16px;
	font-weight: 700;
	cursor: pointer;
}
.eye-panel__small._selected {
	outline: 1px solid #fff;
}
.eye-panel__medium {
	font-size: 21px;
	font-weight: 700;
	cursor: pointer;
}
.eye-panel__medium._selected {
	outline: 1px solid #fff;
}
.eye-panel__big {
	font-size: 26px;
	font-weight: 700;
	cursor: pointer;
}
.eye-panel__big._selected {
	outline: 1px solid #fff;
}
.eye-panel__default {
	font-size: 16px;
	padding: 10px 15px;
	outline: 1px solid #fff;
	cursor: pointer;
}
.eye-panel__default._selected {
	outline-width: 2px;
}
.eye-panel__roll {
	position: absolute;
	bottom: 0;
	left: 50%;
	transform: translate(-50%, 100%);
	padding: 5px 10px;
	background: #3fa6d7;
	font-size: 16px;
	border-radius: 0 0 8px 8px;
	cursor: pointer;
	border-top: 1px solid #ffffff40;
}

